head.script:
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. 샘플실행 후 개발자도구(F12)를 수행하고 body영역에 속성을 확인한다.
    //1. After running the sample, run the developer tool (F12) and check the attributes in the body area.
    //Verify step 1. The name = 'name test', title = 'title test' attribute is rendered in the document.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#trigger1').attr('name') == 'name test'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#trigger1').attr('title') == 'title test'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 02-Mar-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
